-- ============================================================================
-- GLOBAL RESTAURANT EXPLORER PLATFORM — MYSQL 8.0 DATABASE DELIVERABLE
-- ============================================================================
-- Project      : Global Restaurant Explorer Platform
-- Repository   : https://github.com/nhahub/NHA-5-083
-- Source Data  : zomato_cleaned.csv (9,550 rows, 21 columns)
--                Country-Code.xlsx (15 rows, 2 columns)
-- Target RDBMS : MySQL Server 8.0+ / MySQL Workbench 8.0 CE
-- Engine/Chars : InnoDB / utf8mb4 / utf8mb4_0900_ai_ci
-- Architecture : Staging Layer (stg_zomato_cleaned, stg_country_codes) +
--                7 Normalized 3NF Tables (countries, cities, locations,
--                rating_tiers, restaurants, cuisines, restaurant_cuisines) +
--                Analytical View
-- Execution    : Self-contained single-file script. Open in MySQL Workbench
--                8.0 CE and execute directly (no external CSV import needed).
-- ============================================================================

SET NAMES utf8mb4;
SET @OLD_SQL_MODE = @@SQL_MODE;
SET SQL_MODE = 'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';

-- ============================================================================
-- SECTION 1: DATABASE CREATION
-- ============================================================================

DROP DATABASE IF EXISTS zomato_restaurant_explorer;

CREATE DATABASE zomato_restaurant_explorer
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_0900_ai_ci;

USE zomato_restaurant_explorer;

-- ============================================================================
-- SECTION 2: STAGING LAYER (PRESERVES ALL 21 ORIGINAL CSV COLUMNS VERBATIM)
-- ============================================================================
-- Column Mapping (Original CSV -> stg_zomato_cleaned):
--   1.  Restaurant ID        -> restaurant_id
--   2.  Restaurant Name      -> restaurant_name
--   3.  Country Code         -> country_code
--   4.  City                 -> city
--   5.  Address              -> address
--   6.  Locality             -> locality
--   7.  Locality Verbose     -> locality_verbose
--   8.  Longitude            -> longitude
--   9.  Latitude             -> latitude
--   10. Cuisines             -> cuisines
--   11. Average Cost for two -> average_cost_for_two
--   12. Currency             -> currency
--   13. Has Table booking    -> has_table_booking
--   14. Has Online delivery  -> has_online_delivery
--   15. Is delivering now    -> is_delivering_now
--   16. Switch to order menu -> switch_to_order_menu
--   17. Price range          -> price_range
--   18. Aggregate rating     -> aggregate_rating
--   19. Rating color         -> rating_color
--   20. Rating text          -> rating_text
--   21. Votes                -> votes
-- ============================================================================

CREATE TABLE stg_zomato_cleaned (
    restaurant_id        INT UNSIGNED   NOT NULL,
    restaurant_name      VARCHAR(100)   NOT NULL,
    country_code         INT UNSIGNED   NOT NULL,
    city                 VARCHAR(100)   NOT NULL,
    address              VARCHAR(255)   NOT NULL,
    locality             VARCHAR(100)   NOT NULL,
    locality_verbose     VARCHAR(150)   NOT NULL,
    longitude            DECIMAL(12,9)  NULL,
    latitude             DECIMAL(11,9)  NULL,
    cuisines             VARCHAR(255)   NULL,
    average_cost_for_two DECIMAL(10,2)  NOT NULL,
    currency             VARCHAR(50)    NOT NULL,
    has_table_booking    VARCHAR(3)     NOT NULL,
    has_online_delivery  VARCHAR(3)     NOT NULL,
    is_delivering_now    VARCHAR(3)     NOT NULL,
    switch_to_order_menu VARCHAR(3)     NOT NULL,
    price_range          TINYINT UNSIGNED NOT NULL,
    aggregate_rating     DECIMAL(3,1)   NOT NULL,
    rating_color         VARCHAR(20)    NOT NULL,
    rating_text          VARCHAR(20)    NOT NULL,
    votes                INT UNSIGNED   NOT NULL,
    PRIMARY KEY (restaurant_id),
    KEY idx_stg_country_city (country_code, city)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Exact staging copy of zomato_cleaned.csv preserving all 21 columns and 9,550 rows';

-- Column Mapping (Country-Code.xlsx -> stg_country_codes):
--   1.  Country Code -> country_code
--   2.  Country      -> country_name
CREATE TABLE stg_country_codes (
    country_code INT UNSIGNED NOT NULL,
    country_name VARCHAR(100) NOT NULL,
    PRIMARY KEY (country_code),
    UNIQUE KEY uq_stg_country_codes_name (country_name)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Exact staging copy of Country-Code.xlsx preserving all 2 columns and 15 rows';

-- ============================================================================
-- SECTION 3: NORMALIZED 3NF RELATIONAL SCHEMA (7 TABLES + 1 VIEW)
-- ============================================================================

-- 3.1 countries: Distinct numeric country codes and authoritative country names
--     mapped from Country-Code.xlsx (preserving source spellings verbatim).
CREATE TABLE countries (
    country_code INT UNSIGNED NOT NULL,
    country_name VARCHAR(100) NOT NULL,
    PRIMARY KEY (country_code),
    UNIQUE KEY uq_countries_name (country_name),
    CONSTRAINT chk_countries_name_nonempty
        CHECK (CHAR_LENGTH(TRIM(country_name)) > 0)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Normalized country codes and country names mapped from Country-Code.xlsx';

-- 3.2 cities: Cities linked to their country_code with composite uniqueness.
CREATE TABLE cities (
    city_id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
    country_code INT UNSIGNED NOT NULL,
    city_name    VARCHAR(100) NOT NULL,
    PRIMARY KEY (city_id),
    UNIQUE KEY uq_cities_country_city (country_code, city_name),
    KEY idx_cities_name (city_name),
    CONSTRAINT fk_cities_country
        FOREIGN KEY (country_code) REFERENCES countries (country_code)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Normalized cities linked to countries';

-- 3.3 locations: Distinct restaurant addresses and geographic coordinates.
-- Note: Missing coordinates are preserved as NULL (never replaced with 0,0).
--       A stored SHA-256 fingerprint enforces strict uniqueness across all
--       location attributes even when longitude and latitude are NULL.
CREATE TABLE locations (
    location_id      INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    city_id          INT UNSIGNED  NOT NULL,
    address          VARCHAR(255)  NOT NULL,
    locality         VARCHAR(100)  NOT NULL,
    locality_verbose VARCHAR(150)  NOT NULL,
    longitude        DECIMAL(12,9) NULL,
    latitude         DECIMAL(11,9) NULL,
    location_hash    CHAR(64) GENERATED ALWAYS AS (
        SHA2(
            CONCAT_WS(
                '|',
                city_id,
                address,
                locality,
                locality_verbose,
                IFNULL(CAST(longitude AS CHAR), 'NULL'),
                IFNULL(CAST(latitude  AS CHAR), 'NULL')
            ),
            256
        )
    ) STORED,
    PRIMARY KEY (location_id),
    UNIQUE KEY uq_locations_hash (location_hash),
    KEY idx_locations_city_locality (city_id, locality),
    KEY idx_locations_coords (latitude, longitude),
    KEY idx_locations_lookup (city_id, address(100), locality(50)),
    CONSTRAINT fk_locations_city
        FOREIGN KEY (city_id) REFERENCES cities (city_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    CONSTRAINT chk_locations_coords_paired
        CHECK ((longitude IS NULL) = (latitude IS NULL)),
    CONSTRAINT chk_locations_longitude_range
        CHECK (longitude IS NULL OR (longitude BETWEEN -180.000000000 AND 180.000000000)),
    CONSTRAINT chk_locations_latitude_range
        CHECK (latitude IS NULL OR (latitude BETWEEN -90.000000000 AND 90.000000000))
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Normalized geographic locations and addresses (NULL coordinates preserved)';

-- 3.4 rating_tiers: Lookup table eliminating the 3NF transitive dependency
--     between rating_color and rating_text (verified exact 1:1 mapping).
CREATE TABLE rating_tiers (
    rating_tier_id TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
    rating_color   VARCHAR(20)      NOT NULL,
    rating_text    VARCHAR(20)      NOT NULL,
    PRIMARY KEY (rating_tier_id),
    UNIQUE KEY uq_rating_tiers_color (rating_color),
    UNIQUE KEY uq_rating_tiers_text  (rating_text)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Normalized 1:1 lookup of rating_color and rating_text categories';

-- 3.5 restaurants: Primary restaurant entity and operational metrics.
-- Note: Aggregate rating 0.0 is preserved as 0.0 (Not rated), never NULL.
--       Currency is preserved verbatim as Dollar($).
CREATE TABLE restaurants (
    restaurant_id        INT UNSIGNED     NOT NULL,
    restaurant_name      VARCHAR(100)     NOT NULL,
    location_id          INT UNSIGNED     NOT NULL,
    average_cost_for_two DECIMAL(10,2)    NOT NULL,
    currency             VARCHAR(50)      NOT NULL,
    has_table_booking    TINYINT(1)       NOT NULL DEFAULT 0,
    has_online_delivery  TINYINT(1)       NOT NULL DEFAULT 0,
    is_delivering_now    TINYINT(1)       NOT NULL DEFAULT 0,
    switch_to_order_menu TINYINT(1)       NOT NULL DEFAULT 0,
    price_range          TINYINT UNSIGNED NOT NULL,
    aggregate_rating     DECIMAL(3,1)     NOT NULL,
    rating_tier_id       TINYINT UNSIGNED NOT NULL,
    votes                INT UNSIGNED     NOT NULL DEFAULT 0,
    PRIMARY KEY (restaurant_id),
    KEY idx_restaurants_location      (location_id),
    KEY idx_restaurants_rating_tier   (rating_tier_id),
    KEY idx_restaurants_rating_votes  (aggregate_rating DESC, votes DESC),
    KEY idx_restaurants_price_cost    (price_range, average_cost_for_two),
    KEY idx_restaurants_delivery_book (has_online_delivery, has_table_booking),
    KEY idx_restaurants_name          (restaurant_name),
    CONSTRAINT fk_restaurants_location
        FOREIGN KEY (location_id) REFERENCES locations (location_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    CONSTRAINT fk_restaurants_rating_tier
        FOREIGN KEY (rating_tier_id) REFERENCES rating_tiers (rating_tier_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT,
    CONSTRAINT chk_restaurants_cost_nonneg
        CHECK (average_cost_for_two >= 0.00),
    CONSTRAINT chk_restaurants_price_range
        CHECK (price_range BETWEEN 1 AND 4),
    CONSTRAINT chk_restaurants_rating_range
        CHECK (aggregate_rating BETWEEN 0.0 AND 5.0),
    CONSTRAINT chk_restaurants_bool_table_booking
        CHECK (has_table_booking IN (0, 1)),
    CONSTRAINT chk_restaurants_bool_online_delivery
        CHECK (has_online_delivery IN (0, 1)),
    CONSTRAINT chk_restaurants_bool_delivering_now
        CHECK (is_delivering_now IN (0, 1)),
    CONSTRAINT chk_restaurants_bool_switch_menu
        CHECK (switch_to_order_menu IN (0, 1))
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Primary normalized restaurant records';

-- 3.6 cuisines: Atomic, deduplicated cuisine categories (1NF/3NF).
CREATE TABLE cuisines (
    cuisine_id   SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    cuisine_name VARCHAR(50)       NOT NULL,
    PRIMARY KEY (cuisine_id),
    UNIQUE KEY uq_cuisines_name (cuisine_name),
    CONSTRAINT chk_cuisines_nonempty
        CHECK (CHAR_LENGTH(TRIM(cuisine_name)) > 0)
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Distinct atomic cuisine categories extracted from comma-separated Cuisines';

-- 3.7 restaurant_cuisines: Many-to-many bridge table between restaurants and cuisines.
CREATE TABLE restaurant_cuisines (
    restaurant_id INT UNSIGNED      NOT NULL,
    cuisine_id    SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (restaurant_id, cuisine_id),
    KEY idx_rc_cuisine_restaurant (cuisine_id, restaurant_id),
    CONSTRAINT fk_rc_restaurant
        FOREIGN KEY (restaurant_id) REFERENCES restaurants (restaurant_id)
        ON UPDATE RESTRICT
        ON DELETE CASCADE,
    CONSTRAINT fk_rc_cuisine
        FOREIGN KEY (cuisine_id) REFERENCES cuisines (cuisine_id)
        ON UPDATE RESTRICT
        ON DELETE RESTRICT
) ENGINE=InnoDB
  DEFAULT CHARSET=utf8mb4
  COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Many-to-many relationship between restaurants and cuisines';

-- 3.8 Analytical View: Denormalized read-only view for platform queries.
CREATE OR REPLACE VIEW v_restaurant_explorer AS
SELECT
    r.restaurant_id,
    r.restaurant_name,
    co.country_code,
    co.country_name,
    ci.city_id,
    ci.city_name,
    l.location_id,
    l.address,
    l.locality,
    l.locality_verbose,
    l.longitude,
    l.latitude,
    r.average_cost_for_two,
    r.currency,
    r.has_table_booking,
    r.has_online_delivery,
    r.is_delivering_now,
    r.switch_to_order_menu,
    r.price_range,
    r.aggregate_rating,
    rt.rating_color,
    rt.rating_text,
    r.votes
FROM restaurants r
JOIN locations l     ON l.location_id    = r.location_id
JOIN cities ci       ON ci.city_id       = l.city_id
JOIN countries co    ON co.country_code  = ci.country_code
JOIN rating_tiers rt ON rt.rating_tier_id = r.rating_tier_id;

