-- ============================================================================
-- SECTION 5: POPULATE NORMALIZED 3NF TABLES FROM STAGING LAYER
-- ============================================================================

START TRANSACTION;

-- 5.1 Populate countries (15 distinct country codes with names from stg_country_codes)
INSERT INTO countries (country_code, country_name)
SELECT DISTINCT
    s.country_code,
    cc.country_name
FROM stg_zomato_cleaned s
JOIN stg_country_codes cc
  ON cc.country_code = s.country_code
ORDER BY s.country_code;

-- 5.2 Populate cities (141 distinct country_code + city combinations)
INSERT INTO cities (country_code, city_name)
SELECT DISTINCT country_code, city
FROM stg_zomato_cleaned
ORDER BY country_code, city;

-- 5.3 Populate locations (9,453 distinct location combinations)
-- SELECT DISTINCT treats NULL longitude/latitude as equal, cleanly merging
-- identical NULL-coordinate locations while preserving NULL values.
INSERT INTO locations (
    city_id, address, locality, locality_verbose, longitude, latitude
)
SELECT DISTINCT
    ci.city_id,
    s.address,
    s.locality,
    s.locality_verbose,
    s.longitude,
    s.latitude
FROM stg_zomato_cleaned s
JOIN cities ci
  ON ci.country_code = s.country_code
 AND ci.city_name    = s.city
ORDER BY ci.city_id, s.locality, s.address;

-- 5.4 Populate rating_tiers (6 distinct 1:1 rating_color / rating_text tiers)
INSERT INTO rating_tiers (rating_color, rating_text)
SELECT DISTINCT
    rating_color,
    rating_text
FROM stg_zomato_cleaned
ORDER BY rating_text;

-- 5.5 Populate restaurants (9,550 restaurants)
-- Uses MySQL NULL-safe equality (<=>) on longitude and latitude so all 497
-- NULL-coordinate records match their exact normalized location row.
INSERT INTO restaurants (
    restaurant_id,
    restaurant_name,
    location_id,
    average_cost_for_two,
    currency,
    has_table_booking,
    has_online_delivery,
    is_delivering_now,
    switch_to_order_menu,
    price_range,
    aggregate_rating,
    rating_tier_id,
    votes
)
SELECT
    s.restaurant_id,
    s.restaurant_name,
    l.location_id,
    s.average_cost_for_two,
    s.currency,
    CASE WHEN s.has_table_booking    = 'Yes' THEN 1 ELSE 0 END,
    CASE WHEN s.has_online_delivery  = 'Yes' THEN 1 ELSE 0 END,
    CASE WHEN s.is_delivering_now    = 'Yes' THEN 1 ELSE 0 END,
    CASE WHEN s.switch_to_order_menu = 'Yes' THEN 1 ELSE 0 END,
    s.price_range,
    s.aggregate_rating,
    rt.rating_tier_id,
    s.votes
FROM stg_zomato_cleaned s
JOIN cities ci
  ON ci.country_code = s.country_code
 AND ci.city_name    = s.city
JOIN locations l
  ON l.city_id          = ci.city_id
 AND l.address          = s.address
 AND l.locality         = s.locality
 AND l.locality_verbose = s.locality_verbose
 AND l.longitude       <=> s.longitude
 AND l.latitude        <=> s.latitude
JOIN rating_tiers rt
  ON rt.rating_color = s.rating_color
 AND rt.rating_text  = s.rating_text
ORDER BY s.restaurant_id;

-- 5.6 Populate cuisines (145 distinct atomic cuisines via MySQL 8.0 Recursive CTE)
-- Trims whitespace, skips NULL/empty strings, and deduplicates categories.
INSERT INTO cuisines (cuisine_name)
WITH RECURSIVE cuisine_split AS (
    SELECT
        restaurant_id,
        CAST(TRIM(SUBSTRING_INDEX(cuisines, ',', 1)) AS CHAR(255)) AS cuisine_name,
        CAST(
            CASE
                WHEN LOCATE(',', cuisines) > 0
                THEN SUBSTRING(cuisines, LOCATE(',', cuisines) + 1)
                ELSE ''
            END
            AS CHAR(255)
        ) AS remaining
    FROM stg_zomato_cleaned
    WHERE cuisines IS NOT NULL
      AND TRIM(cuisines) <> ''
    UNION ALL
    SELECT
        restaurant_id,
        CAST(TRIM(SUBSTRING_INDEX(remaining, ',', 1)) AS CHAR(255)) AS cuisine_name,
        CAST(
            CASE
                WHEN LOCATE(',', remaining) > 0
                THEN SUBSTRING(remaining, LOCATE(',', remaining) + 1)
                ELSE ''
            END
            AS CHAR(255)
        ) AS remaining
    FROM cuisine_split
    WHERE remaining <> ''
)
SELECT DISTINCT cuisine_name
FROM cuisine_split
WHERE cuisine_name <> ''
ORDER BY cuisine_name;

-- 5.7 Populate restaurant_cuisines (19,703 unique restaurant-cuisine pairs)
-- SELECT DISTINCT cleanly deduplicates the 5 source restaurants whose raw
-- comma-separated Cuisines string repeats a cuisine name within the same row.
INSERT INTO restaurant_cuisines (restaurant_id, cuisine_id)
WITH RECURSIVE cuisine_split AS (
    SELECT
        restaurant_id,
        CAST(TRIM(SUBSTRING_INDEX(cuisines, ',', 1)) AS CHAR(255)) AS cuisine_name,
        CAST(
            CASE
                WHEN LOCATE(',', cuisines) > 0
                THEN SUBSTRING(cuisines, LOCATE(',', cuisines) + 1)
                ELSE ''
            END
            AS CHAR(255)
        ) AS remaining
    FROM stg_zomato_cleaned
    WHERE cuisines IS NOT NULL
      AND TRIM(cuisines) <> ''
    UNION ALL
    SELECT
        restaurant_id,
        CAST(TRIM(SUBSTRING_INDEX(remaining, ',', 1)) AS CHAR(255)) AS cuisine_name,
        CAST(
            CASE
                WHEN LOCATE(',', remaining) > 0
                THEN SUBSTRING(remaining, LOCATE(',', remaining) + 1)
                ELSE ''
            END
            AS CHAR(255)
        ) AS remaining
    FROM cuisine_split
    WHERE remaining <> ''
)
SELECT DISTINCT
    cs.restaurant_id,
    c.cuisine_id
FROM cuisine_split cs
JOIN cuisines c
  ON c.cuisine_name = cs.cuisine_name
WHERE cs.cuisine_name <> ''
ORDER BY cs.restaurant_id, c.cuisine_id;

COMMIT;

-- ============================================================================
-- SECTION 6: POST-LOAD INTEGRITY & VALIDATION QUERIES
-- ============================================================================

-- 6.1 Table Row-Count Audit (Expected vs. Actual)
SELECT 'stg_zomato_cleaned'  AS table_name, COUNT(*) AS actual_rows, 9550  AS expected_rows, CASE WHEN COUNT(*) = 9550  THEN 'PASS' ELSE 'FAIL' END AS status FROM stg_zomato_cleaned
UNION ALL
SELECT 'stg_country_codes',                 COUNT(*),                15,                    CASE WHEN COUNT(*) = 15    THEN 'PASS' ELSE 'FAIL' END           FROM stg_country_codes
UNION ALL
SELECT 'countries',                         COUNT(*),                15,                    CASE WHEN COUNT(*) = 15    THEN 'PASS' ELSE 'FAIL' END           FROM countries
UNION ALL
SELECT 'cities',                            COUNT(*),                141,                   CASE WHEN COUNT(*) = 141   THEN 'PASS' ELSE 'FAIL' END           FROM cities
UNION ALL
SELECT 'locations',                         COUNT(*),                9453,                  CASE WHEN COUNT(*) = 9453  THEN 'PASS' ELSE 'FAIL' END           FROM locations
UNION ALL
SELECT 'rating_tiers',                      COUNT(*),                6,                     CASE WHEN COUNT(*) = 6     THEN 'PASS' ELSE 'FAIL' END           FROM rating_tiers
UNION ALL
SELECT 'restaurants',                       COUNT(*),                9550,                  CASE WHEN COUNT(*) = 9550  THEN 'PASS' ELSE 'FAIL' END           FROM restaurants
UNION ALL
SELECT 'cuisines',                          COUNT(*),                145,                   CASE WHEN COUNT(*) = 145   THEN 'PASS' ELSE 'FAIL' END           FROM cuisines
UNION ALL
SELECT 'restaurant_cuisines',               COUNT(*),                19703,                 CASE WHEN COUNT(*) = 19703 THEN 'PASS' ELSE 'FAIL' END           FROM restaurant_cuisines;

-- 6.2 Staging-to-Normalized Full-Fidelity Reconciliation (Expect 0 mismatches)
SELECT
    COUNT(*) AS mismatched_records,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS status
FROM stg_zomato_cleaned s
LEFT JOIN stg_country_codes cc
  ON cc.country_code = s.country_code
LEFT JOIN v_restaurant_explorer v
  ON v.restaurant_id = s.restaurant_id
WHERE v.restaurant_id IS NULL
   OR cc.country_code IS NULL
   OR v.restaurant_name      <> s.restaurant_name
   OR v.country_code         <> s.country_code
   OR v.country_name         <> cc.country_name
   OR v.city_name            <> s.city
   OR v.address              <> s.address
   OR v.locality             <> s.locality
   OR v.locality_verbose     <> s.locality_verbose
   OR NOT (v.longitude      <=> s.longitude)
   OR NOT (v.latitude       <=> s.latitude)
   OR v.average_cost_for_two <> s.average_cost_for_two
   OR v.currency             <> s.currency
   OR v.has_table_booking    <> (CASE WHEN s.has_table_booking    = 'Yes' THEN 1 ELSE 0 END)
   OR v.has_online_delivery  <> (CASE WHEN s.has_online_delivery  = 'Yes' THEN 1 ELSE 0 END)
   OR v.is_delivering_now    <> (CASE WHEN s.is_delivering_now    = 'Yes' THEN 1 ELSE 0 END)
   OR v.switch_to_order_menu <> (CASE WHEN s.switch_to_order_menu = 'Yes' THEN 1 ELSE 0 END)
   OR v.price_range          <> s.price_range
   OR v.aggregate_rating     <> s.aggregate_rating
   OR v.rating_color         <> s.rating_color
   OR v.rating_text          <> s.rating_text
   OR v.votes                <> s.votes;

-- 6.3 Missing Coordinates & Missing Cuisines Preservation Audit
SELECT
    'Restaurants with NULL coordinates' AS check_name,
    COUNT(*)                            AS actual_count,
    497                                 AS expected_count,
    CASE WHEN COUNT(*) = 497 THEN 'PASS' ELSE 'FAIL' END AS status
FROM v_restaurant_explorer
WHERE longitude IS NULL AND latitude IS NULL
UNION ALL
SELECT
    'Restaurants with 0 cuisines (NULL in CSV)',
    COUNT(*),
    9,
    CASE WHEN COUNT(*) = 9 THEN 'PASS' ELSE 'FAIL' END
FROM restaurants r
LEFT JOIN restaurant_cuisines rc ON rc.restaurant_id = r.restaurant_id
WHERE rc.restaurant_id IS NULL
UNION ALL
SELECT
    'Restaurants rated 0.0 (Not rated)',
    COUNT(*),
    2147,
    CASE WHEN COUNT(*) = 2147 THEN 'PASS' ELSE 'FAIL' END
FROM v_restaurant_explorer
WHERE aggregate_rating = 0.0 AND rating_text = 'Not rated';

-- 6.4 Referential Integrity Orphan Check (Expect 0 orphans across all FKs)
SELECT 'cities -> countries'             AS fk_relationship, COUNT(*) AS orphan_count FROM cities ci       LEFT JOIN countries co   ON co.country_code   = ci.country_code   WHERE co.country_code   IS NULL
UNION ALL
SELECT 'locations -> cities',                                COUNT(*)                 FROM locations l     LEFT JOIN cities ci      ON ci.city_id        = l.city_id         WHERE ci.city_id        IS NULL
UNION ALL
SELECT 'restaurants -> locations',                           COUNT(*)                 FROM restaurants r   LEFT JOIN locations l    ON l.location_id     = r.location_id     WHERE l.location_id     IS NULL
UNION ALL
SELECT 'restaurants -> rating_tiers',                        COUNT(*)                 FROM restaurants r   LEFT JOIN rating_tiers rt ON rt.rating_tier_id = r.rating_tier_id WHERE rt.rating_tier_id IS NULL
UNION ALL
SELECT 'restaurant_cuisines -> restaurants',                 COUNT(*)                 FROM restaurant_cuisines rc LEFT JOIN restaurants r ON r.restaurant_id = rc.restaurant_id WHERE r.restaurant_id IS NULL
UNION ALL
SELECT 'restaurant_cuisines -> cuisines',                    COUNT(*)                 FROM restaurant_cuisines rc LEFT JOIN cuisines c    ON c.cuisine_id    = rc.cuisine_id    WHERE c.cuisine_id    IS NULL;

-- ============================================================================
-- SECTION 7: PLATFORM ANALYTICAL & EXPLORER SAMPLE QUERIES (10 QUERIES)
-- ============================================================================

-- Q1: Top 10 Cities by Restaurant Count and Average Rating (Rated Only)
SELECT
    co.country_code,
    co.country_name,
    ci.city_name,
    COUNT(r.restaurant_id) AS total_restaurants,
    SUM(CASE WHEN r.aggregate_rating > 0 THEN 1 ELSE 0 END) AS rated_restaurants,
    ROUND(AVG(CASE WHEN r.aggregate_rating > 0 THEN r.aggregate_rating END), 2) AS avg_rating_rated_only,
    ROUND(AVG(r.average_cost_for_two), 2) AS avg_cost_for_two
FROM restaurants r
JOIN locations l  ON l.location_id   = r.location_id
JOIN cities ci    ON ci.city_id      = l.city_id
JOIN countries co ON co.country_code = ci.country_code
GROUP BY co.country_code, co.country_name, ci.city_id, ci.city_name
ORDER BY total_restaurants DESC
LIMIT 10;

-- Q2: Top 15 Most Popular Cuisines Globally with Average Rating & Votes
SELECT
    c.cuisine_name,
    COUNT(rc.restaurant_id) AS restaurant_count,
    ROUND(AVG(CASE WHEN r.aggregate_rating > 0 THEN r.aggregate_rating END), 2) AS avg_rated_score,
    SUM(r.votes) AS total_votes
FROM cuisines c
JOIN restaurant_cuisines rc ON rc.cuisine_id    = c.cuisine_id
JOIN restaurants r          ON r.restaurant_id  = rc.restaurant_id
GROUP BY c.cuisine_id, c.cuisine_name
ORDER BY restaurant_count DESC
LIMIT 15;

-- Q3: Restaurant Distribution by Country
SELECT
    co.country_code,
    co.country_name,
    COUNT(DISTINCT ci.city_id) AS city_count,
    COUNT(r.restaurant_id) AS restaurant_count,
    ROUND(100.0 * COUNT(r.restaurant_id) / (SELECT COUNT(*) FROM restaurants), 2) AS pct_of_total,
    ROUND(AVG(CASE WHEN r.aggregate_rating > 0 THEN r.aggregate_rating END), 2) AS avg_rating_rated_only
FROM countries co
JOIN cities ci     ON ci.country_code = co.country_code
JOIN locations l   ON l.city_id       = ci.city_id
JOIN restaurants r ON r.location_id   = l.location_id
GROUP BY co.country_code, co.country_name
ORDER BY restaurant_count DESC;

-- Q4: Rating Tier Distribution with Min/Max Rating Bounds and Average Votes
SELECT
    rt.rating_text,
    rt.rating_color,
    COUNT(r.restaurant_id) AS restaurant_count,
    MIN(r.aggregate_rating) AS min_rating,
    MAX(r.aggregate_rating) AS max_rating,
    ROUND(AVG(r.votes), 1) AS avg_votes
FROM rating_tiers rt
JOIN restaurants r ON r.rating_tier_id = rt.rating_tier_id
GROUP BY rt.rating_tier_id, rt.rating_text, rt.rating_color
ORDER BY max_rating DESC;

-- Q5: Price Range Breakdown (Cost, Rating, Table Booking & Online Delivery Rates)
SELECT
    r.price_range,
    COUNT(*) AS restaurant_count,
    ROUND(MIN(r.average_cost_for_two), 2) AS min_cost,
    ROUND(AVG(r.average_cost_for_two), 2) AS avg_cost,
    ROUND(MAX(r.average_cost_for_two), 2) AS max_cost,
    ROUND(AVG(CASE WHEN r.aggregate_rating > 0 THEN r.aggregate_rating END), 2) AS avg_rating_rated_only,
    ROUND(100.0 * AVG(r.has_table_booking), 2)   AS pct_table_booking,
    ROUND(100.0 * AVG(r.has_online_delivery), 2) AS pct_online_delivery
FROM restaurants r
GROUP BY r.price_range
ORDER BY r.price_range;

-- Q6: Top 10 Highest-Rated Restaurants with At Least 1,000 Votes
SELECT
    v.restaurant_id,
    v.restaurant_name,
    v.city_name,
    v.country_code,
    v.country_name,
    v.aggregate_rating,
    v.rating_text,
    v.votes,
    v.average_cost_for_two,
    v.currency
FROM v_restaurant_explorer v
WHERE v.votes >= 1000
ORDER BY v.aggregate_rating DESC, v.votes DESC
LIMIT 10;

-- Q7: Online Delivery & Table Booking Feature Matrix
SELECT
    r.has_table_booking,
    r.has_online_delivery,
    COUNT(*) AS restaurant_count,
    ROUND(AVG(CASE WHEN r.aggregate_rating > 0 THEN r.aggregate_rating END), 2) AS avg_rating_rated_only,
    ROUND(AVG(r.votes), 1) AS avg_votes,
    ROUND(AVG(r.average_cost_for_two), 2) AS avg_cost_for_two
FROM restaurants r
GROUP BY r.has_table_booking, r.has_online_delivery
ORDER BY r.has_table_booking DESC, r.has_online_delivery DESC;

-- Q8: Restaurants Offering the Most Distinct Cuisines (Top 10)
SELECT
    r.restaurant_id,
    r.restaurant_name,
    ci.city_name,
    COUNT(rc.cuisine_id) AS cuisine_count,
    GROUP_CONCAT(c.cuisine_name ORDER BY c.cuisine_name SEPARATOR ', ') AS cuisines_list
FROM restaurants r
JOIN locations l            ON l.location_id    = r.location_id
JOIN cities ci              ON ci.city_id       = l.city_id
JOIN restaurant_cuisines rc ON rc.restaurant_id = r.restaurant_id
JOIN cuisines c             ON c.cuisine_id     = rc.cuisine_id
GROUP BY r.restaurant_id, r.restaurant_name, ci.city_name
ORDER BY cuisine_count DESC, r.votes DESC
LIMIT 10;

-- Q9: Shared Locations Hosting Multiple Restaurants (Top 10 Addresses)
SELECT
    l.location_id,
    ci.city_name,
    l.locality,
    l.address,
    COUNT(r.restaurant_id) AS restaurants_at_location,
    ROUND(AVG(CASE WHEN r.aggregate_rating > 0 THEN r.aggregate_rating END), 2) AS avg_rating_rated_only
FROM locations l
JOIN cities ci     ON ci.city_id     = l.city_id
JOIN restaurants r ON r.location_id  = l.location_id
GROUP BY l.location_id, ci.city_name, l.locality, l.address
HAVING COUNT(r.restaurant_id) > 1
ORDER BY restaurants_at_location DESC, l.location_id ASC
LIMIT 10;

-- Q10: Geographic Coordinate Completeness by Country
SELECT
    co.country_code,
    co.country_name,
    COUNT(r.restaurant_id) AS total_restaurants,
    SUM(CASE WHEN l.longitude IS NOT NULL AND l.latitude IS NOT NULL THEN 1 ELSE 0 END) AS with_coordinates,
    SUM(CASE WHEN l.longitude IS NULL     AND l.latitude IS NULL     THEN 1 ELSE 0 END) AS missing_coordinates,
    ROUND(100.0 * SUM(CASE WHEN l.longitude IS NOT NULL THEN 1 ELSE 0 END) / COUNT(r.restaurant_id), 2) AS pct_geolocated
FROM countries co
JOIN cities ci     ON ci.country_code = co.country_code
JOIN locations l   ON l.city_id       = ci.city_id
JOIN restaurants r ON r.location_id   = l.location_id
GROUP BY co.country_code, co.country_name
ORDER BY missing_coordinates DESC, total_restaurants DESC;

-- ============================================================================
-- SECTION 8: FINAL DATABASE VERIFICATION SUMMARY
-- ============================================================================

SELECT
    DATABASE()                                         AS active_database,
    (SELECT COUNT(*) FROM stg_zomato_cleaned)          AS staging_rows,
    (SELECT COUNT(*) FROM stg_country_codes)           AS country_code_staging_rows,
    (SELECT COUNT(*) FROM countries)                   AS countries_count,
    (SELECT COUNT(*) FROM cities)                      AS cities_count,
    (SELECT COUNT(*) FROM locations)                   AS locations_count,
    (SELECT COUNT(*) FROM rating_tiers)                AS rating_tiers_count,
    (SELECT COUNT(*) FROM restaurants)                 AS restaurants_count,
    (SELECT COUNT(*) FROM cuisines)                    AS cuisines_count,
    (SELECT COUNT(*) FROM restaurant_cuisines)         AS restaurant_cuisines_count,
    'READY'                                            AS deployment_status;

SET SQL_MODE = @OLD_SQL_MODE;